        """Compact chat-list records for the operator UI."""
        clauses = ""
        values: list[object] = [limit]
        if source:
            if source == "gmail":
                clauses = "WHERE (c.source=? OR c.source LIKE ?)"
                values[0:0] = [source, "gmail:%"]
